import ctypes as c, time
from ctypes import wintypes as w
from pywinauto import Desktop
import psutil

shell32=c.windll.shell32
shell32.ShellExecuteW(None,"open","ms-settings:display",None,None,1)
deadline=time.monotonic()+15
spec=None
while time.monotonic()<deadline:
    for x in Desktop(backend="uia").windows():
        try:
            pname=psutil.Process(x.element_info.process_id).name().lower()
            title=x.window_text()
            if pname=="applicationframehost.exe" and title:
                spec=Desktop(backend="uia").window(handle=x.handle)
                break
        except Exception:
            pass
    if spec is not None: break
    time.sleep(.25)
if spec is None: raise RuntimeError("Settings host window not found")
wrap=spec.wrapper_object()
time.sleep(2)
print("SETTINGS_HOST",repr(wrap.window_text()),flush=True)
nodes=wrap.descendants()
print("NODE_COUNT",len(nodes),flush=True)
for x in nodes:
    try:
        ct=x.element_info.control_type
        name=(x.element_info.name or x.window_text() or "").strip()
        aid=x.element_info.automation_id or ""
        if ct in ("ComboBox","ListItem","Button","Text","Slider"):
            if ct=="ComboBox" or "%" in name or "100" in name or "125" in name or "150" in name or "200" in name:
                print("CONTROL",ct,repr(aid),repr(name),flush=True)
    except Exception:
        pass
try: wrap.close()
except Exception: pass

